window.LESSON_DATA = {"schemaVersion":"2.0.0","version":"2.0.0","buildDate":"2026-08-01","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":2,"title":"Functions"},"lesson":{"number":"2.4","slug":"exponential-logarithmic-models","title":"Exponential and Logarithmic Models","subtitle":"Interpret repeated percentage change, solve threshold problems and connect logarithmic scales to inverse exponential reasoning.","syllabus_focus":"Exponential growth and decay, transformed exponential models, technology-based equations, logarithms and contextual scales.","skill_keys":["IBAI.U2.EXP_LOG"],"objectives":["Interpret parameters in exponential growth and decay models.","Solve exponential equations graphically and with logarithms where appropriate.","Use doubling time, half-life and asymptotic behaviour in context.","Interpret logarithmic scales and compare additive with multiplicative change."],"vocab":["growth factor","decay factor","initial value","horizontal asymptote","doubling time","half-life","logarithm","natural logarithm","exponential equation","logarithmic scale"],"technology":"Graph both sides or use numerical solve for threshold equations; retain unrounded values and report the first whole time interval that satisfies a contextual condition.","inquiry":"Two quantities start together. One adds a fixed amount; the other grows by a fixed percentage. Which becomes larger, when does it happen, and how reliable is the prediction?"},"slides":[{"section":"Launch","title":"Exponential and Logarithmic Models","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB Mathematics: Applications and Interpretation SL</div><div class=\"cover-number\">2.4</div><h1>Exponential and Logarithmic Models</h1><p class=\"cover-subtitle\">Interpret repeated percentage change, solve threshold problems and connect logarithmic scales to inverse exponential reasoning.</p><div class=\"pill-row\"><span>Inquiry</span><span>Technology</span><span>Modelling</span><span>Interpretation</span><span>Evaluation</span></div><button class=\"primary-btn route-jump\" data-go=\"practice\">Open Practice Studio</button></div><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div></div>","kind":"cover","eyebrow":"Unit 2 · Functions"},{"section":"Launch","title":"Inquiry launch","html":"<div class=\"launch-panel\"><h2>Start with a decision</h2><p>Two quantities start together. One adds a fixed amount; the other grows by a fixed percentage. Which becomes larger, when does it happen, and how reliable is the prediction?</p><textarea class=\"student-note\" data-note=\"inquiry\" placeholder=\"Write an initial model, assumption or question before continuing.\"></textarea></div>","kind":"content","eyebrow":"Think before calculating"},{"section":"Launch","title":"Learning outcomes","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"obj-2.4-0\"><span>Interpret parameters in exponential growth and decay models.</span></label><label><input type=checkbox data-reflect=\"obj-2.4-1\"><span>Solve exponential equations graphically and with logarithms where appropriate.</span></label><label><input type=checkbox data-reflect=\"obj-2.4-2\"><span>Use doubling time, half-life and asymptotic behaviour in context.</span></label><label><input type=checkbox data-reflect=\"obj-2.4-3\"><span>Interpret logarithmic scales and compare additive with multiplicative change.</span></label></div>","kind":"content","eyebrow":"By the end"},{"section":"Launch","title":"Diagnostic checkpoint","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Prior knowledge</h2><p>Coordinate axes, substitution, equation solving, percentage change and clear use of units.</p></article><article class=\"focus-card\"><h2>Quick self-check</h2><p>Can you distinguish an input restriction from a graphing-window choice? Can you explain what a parameter means in context?</p></article></div><textarea class=\"student-note\" data-note=\"diagnostic\" placeholder=\"Record one strength and one question.\"></textarea>","kind":"content","eyebrow":"Activate prior learning"},{"section":"Launch","title":"Vocabulary and notation","html":"<div class=\"vocab-grid\"><span class=vocab-chip>growth factor</span><span class=vocab-chip>decay factor</span><span class=vocab-chip>initial value</span><span class=vocab-chip>horizontal asymptote</span><span class=vocab-chip>doubling time</span><span class=vocab-chip>half-life</span><span class=vocab-chip>logarithm</span><span class=vocab-chip>natural logarithm</span><span class=vocab-chip>exponential equation</span><span class=vocab-chip>logarithmic scale</span></div><div class=\"callout\"><b>Communication standard:</b> define every variable, include units, and distinguish an exact result from a rounded interpretation.</div>","kind":"content","eyebrow":"Language matters"},{"section":"Launch","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Calculate / Find</b><span>Show relevant stages and a defensible final value.</span></div><div><b>Determine</b><span>Obtain the only possible answer.</span></div><div><b>Interpret</b><span>Connect the mathematics to variables, units and context.</span></div><div><b>Explain / Justify</b><span>Give mathematical reasons, not only a conclusion.</span></div><div><b>Evaluate / Comment</b><span>Judge validity using evidence, assumptions and limitations.</span></div><div><b>Construct / Sketch</b><span>Communicate an accurate, labelled representation.</span></div></div>","kind":"content","eyebrow":"Answer the verb"},{"section":"Launch","title":"Technology contract","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Purpose</h2><p>Graph both sides or use numerical solve for threshold equations; retain unrounded values and report the first whole time interval that satisfies a contextual condition.</p></article><article class=\"focus-card\"><h2>Evidence to record</h2><p>Window/domain, equation or list entered, relevant output, units, rounding and a sentence interpreting the result.</p></article></div>","kind":"content","eyebrow":"GDC is a reasoning tool"},{"section":"Launch","title":"Lesson pathway","html":"<div class=\"workflow\"><div><b>1</b><span>Learn concepts through representations.</span></div><div><b>2</b><span>Investigate with technology.</span></div><div><b>3</b><span>Practise across four levels.</span></div><div><b>4</b><span>Complete IB tasks and a timed quiz.</span></div><div><b>5</b><span>Review evidence and mark completion.</span></div></div>","kind":"content","eyebrow":"Learn · practise · master"},{"section":"Concept cycle 1","title":"Multiplicative change","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>An exponential model multiplies by the same factor over equal input intervals. The factor is 1+r for growth and 1−r for decay.</p></article><div class=\"formula-panel\">\\[A(t)=A_0b^t\\]</div></div>","kind":"content","eyebrow":"1 of 8"},{"section":"Concept cycle 1","title":"Multiplicative change: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for multiplicative change?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 1","title":"Worked example: Multiplicative change","html":"<div class=\"worked\"><h2>A population starts at 850 and grows by 6% per year. Write a model.</h2><ol class=\"method\"><li>Initial value A₀=850.</li><li>Growth factor b=1.06.</li><li>A(t)=850(1.06)^t.</li></ol><div class=\"formula-panel\">\\[A(t)=A_0b^t\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 1","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>A device worth QAR 7200 depreciates by 18% each year. Write a value model.</b></div><textarea class=\"student-note tall\" data-note=\"turn-1\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">V(t)=7200(0.82)^t.</div></details></div>","kind":"content","eyebrow":"Multiplicative change"},{"section":"Concept cycle 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A 6% increase means add 0.06.”</p><h3>Repair</h3><p>Percentage change multiplies the current amount by 1.06.</p></div></div>","kind":"content","eyebrow":"Multiplicative change"},{"section":"Concept cycle 2","title":"Parameters and asymptotes","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>In y=a·bˣ+c, c is the horizontal asymptote and a+c is the y-intercept. The sign of a controls which side of the asymptote the graph occupies.</p></article><div class=\"formula-panel\">\\[f(x)=a b^x+c\\]</div></div>","kind":"content","eyebrow":"2 of 8"},{"section":"Concept cycle 2","title":"Parameters and asymptotes: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for parameters and asymptotes?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 2","title":"Worked example: Parameters and asymptotes","html":"<div class=\"worked\"><h2>For f(x)=5(0.7)^x+12, state the y-intercept and horizontal asymptote.</h2><ol class=\"method\"><li>f(0)=5+12=17.</li><li>As x→∞, 0.7^x→0.</li><li>Horizontal asymptote y=12.</li></ol><div class=\"formula-panel\">\\[f(x)=a b^x+c\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 2","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>For g(x)=−8(1.3)^x+20, state g(0) and the asymptote.</b></div><textarea class=\"student-note tall\" data-note=\"turn-2\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">g(0)=12 and the asymptote is y=20.</div></details></div>","kind":"content","eyebrow":"Parameters and asymptotes"},{"section":"Concept cycle 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“The horizontal asymptote is y=a.”</p><h3>Repair</h3><p>The vertical shift c is the horizontal asymptote.</p></div></div>","kind":"content","eyebrow":"Parameters and asymptotes"},{"section":"Concept cycle 3","title":"Solving exponential equations","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Threshold equations can be solved by graph intersection, numerical solve or logarithms. In discrete contexts, interpret the first integer time that satisfies the condition.</p></article><div class=\"formula-panel\">\\[A_0b^t=T\\Rightarrow t=\\frac{\\ln(T/A_0)}{\\ln b}\\]</div></div>","kind":"content","eyebrow":"3 of 8"},{"section":"Concept cycle 3","title":"Solving exponential equations: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for solving exponential equations?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 3","title":"Worked example: Solving exponential equations","html":"<div class=\"worked\"><h2>Solve 600(1.08)^t=1000.</h2><ol class=\"method\"><li>Divide by 600.</li><li>Take natural logs.</li><li>t=ln(1000/600)/ln(1.08)≈6.64.</li></ol><div class=\"formula-panel\">\\[A_0b^t=T\\Rightarrow t=\\frac{\\ln(T/A_0)}{\\ln b}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 3","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Solve 3200(0.86)^t=1000.</b></div><textarea class=\"student-note tall\" data-note=\"turn-3\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">t=ln(1000/3200)/ln(0.86)≈7.72.</div></details></div>","kind":"content","eyebrow":"Solving exponential equations"},{"section":"Concept cycle 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Take the logarithm of only one side.”</p><h3>Repair</h3><p>Apply the same operation to both sides after isolating the exponential term.</p></div></div>","kind":"content","eyebrow":"Solving exponential equations"},{"section":"Concept cycle 4","title":"Doubling time and half-life","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Doubling and half-life depend only on the multiplicative factor when the asymptote is zero. They are logarithmic threshold times.</p></article><div class=\"formula-panel\">\\[T_2=\\frac{\\ln2}{\\ln b},\\quad T_{1/2}=\\frac{\\ln0.5}{\\ln b}\\]</div></div>","kind":"content","eyebrow":"4 of 8"},{"section":"Concept cycle 4","title":"Doubling time and half-life: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for doubling time and half-life?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 4","title":"Worked example: Doubling time and half-life","html":"<div class=\"worked\"><h2>Find the doubling time for 4.5% annual growth.</h2><ol class=\"method\"><li>Use b=1.045.</li><li>T₂=ln2/ln1.045.</li><li>T₂≈15.7 years.</li></ol><div class=\"formula-panel\">\\[T_2=\\frac{\\ln2}{\\ln b},\\quad T_{1/2}=\\frac{\\ln0.5}{\\ln b}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 4","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Find the half-life of a quantity that retains 82% each hour.</b></div><textarea class=\"student-note tall\" data-note=\"turn-4\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">ln(0.5)/ln(0.82)≈3.49 hours.</div></details></div>","kind":"content","eyebrow":"Doubling time and half-life"},{"section":"Concept cycle 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A 20% decay has half-life 2.5 intervals because 50/20=2.5.”</p><h3>Repair</h3><p>Decay acts on the remaining amount, so use powers or logarithms.</p></div></div>","kind":"content","eyebrow":"Doubling time and half-life"},{"section":"Concept cycle 5","title":"Logarithms as inverse exponents","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>The statement log_b(a)=x is equivalent to bˣ=a. Domain restrictions require a>0 and b>0, b≠1.</p></article><div class=\"formula-panel\">\\[b^x=a\\iff x=\\log_b a\\]</div></div>","kind":"content","eyebrow":"5 of 8"},{"section":"Concept cycle 5","title":"Logarithms as inverse exponents: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for logarithms as inverse exponents?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 5","title":"Worked example: Logarithms as inverse exponents","html":"<div class=\"worked\"><h2>Evaluate log₁₀(0.001) and explain.</h2><ol class=\"method\"><li>0.001=10⁻³.</li><li>Therefore log₁₀(0.001)=−3.</li><li>The logarithm records the exponent.</li></ol><div class=\"formula-panel\">\\[b^x=a\\iff x=\\log_b a\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 5","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Evaluate log₂(32) and log₅(1/25).</b></div><textarea class=\"student-note tall\" data-note=\"turn-5\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">5 and −2.</div></details></div>","kind":"content","eyebrow":"Logarithms as inverse exponents"},{"section":"Concept cycle 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“log(a+b)=log a+log b.”</p><h3>Repair</h3><p>Logarithm laws apply to products and quotients, not sums.</p></div></div>","kind":"content","eyebrow":"Logarithms as inverse exponents"},{"section":"Concept cycle 6","title":"Logarithmic scales","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>On a base-10 logarithmic scale, multiplying the underlying quantity by 10 adds 1 to the scale value. Differences represent ratios.</p></article><div class=\"formula-panel\">\\[L=\\log_{10}Q\\]</div></div>","kind":"content","eyebrow":"6 of 8"},{"section":"Concept cycle 6","title":"Logarithmic scales: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for logarithmic scales?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 6","title":"Worked example: Logarithmic scales","html":"<div class=\"worked\"><h2>If an amplitude rises by a factor of 100, how much does L increase?</h2><ol class=\"method\"><li>100=10².</li><li>log₁₀(100Q)=log₁₀Q+2.</li><li>The scale increases by 2.</li></ol><div class=\"formula-panel\">\\[L=\\log_{10}Q\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 6","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Hydrogen-ion concentration increases by a factor of 10. How does pH=−log₁₀C change?</b></div><textarea class=\"student-note tall\" data-note=\"turn-6\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">pH decreases by 1.</div></details></div>","kind":"content","eyebrow":"Logarithmic scales"},{"section":"Concept cycle 6","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A one-unit change on a log scale is a one-unit change in the original quantity.”</p><h3>Repair</h3><p>It usually represents a multiplicative factor.</p></div></div>","kind":"content","eyebrow":"Logarithmic scales"},{"section":"Concept cycle 7","title":"Comparing linear and exponential models","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Linear change has constant first differences; exponential change has constant ratios. Exponential growth eventually exceeds any positive-gradient linear model.</p></article><div class=\"formula-panel\">\\[L(t)=a+dt,\\quad E(t)=Ab^t\\]</div></div>","kind":"content","eyebrow":"7 of 8"},{"section":"Concept cycle 7","title":"Comparing linear and exponential models: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for comparing linear and exponential models?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 7","title":"Worked example: Comparing linear and exponential models","html":"<div class=\"worked\"><h2>Compare 500+80t with 500(1.08)^t for long-term growth.</h2><ol class=\"method\"><li>Both start at 500.</li><li>The linear model adds 80 each interval.</li><li>The exponential model compounds and eventually dominates.</li></ol><div class=\"formula-panel\">\\[L(t)=a+dt,\\quad E(t)=Ab^t\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 7","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>A table has values 240, 300, 375, 468.75. Identify the model type and factor.</b></div><textarea class=\"student-note tall\" data-note=\"turn-7\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Exponential; each term is multiplied by 1.25.</div></details></div>","kind":"content","eyebrow":"Comparing linear and exponential models"},{"section":"Concept cycle 7","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“If an exponential model starts slowly, it will always remain smaller.”</p><h3>Repair</h3><p>Compounding changes the rate itself.</p></div></div>","kind":"content","eyebrow":"Comparing linear and exponential models"},{"section":"Concept cycle 8","title":"Validity, saturation and shifted models","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Real growth often slows because resources are limited. A shifted or bounded model may be more plausible than unbounded exponential growth.</p></article><div class=\"formula-panel\">\\[P(t)=L-Ae^{-kt}\\]</div></div>","kind":"content","eyebrow":"8 of 8"},{"section":"Concept cycle 8","title":"Validity, saturation and shifted models: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"exponential and logarithmic models\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C120 202,195 195,265 165 S390 78,475 42\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"35\" y1=\"205\" x2=\"490\" y2=\"205\" stroke=\"#D4A72C\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">exponential and logarithmic models</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for validity, saturation and shifted models?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 8","title":"Worked example: Validity, saturation and shifted models","html":"<div class=\"worked\"><h2>Interpret L in P(t)=120−95e⁻⁰·³t.</h2><ol class=\"method\"><li>As t increases, e⁻⁰·³t→0.</li><li>P(t) approaches 120.</li><li>L=120 is the limiting value.</li></ol><div class=\"formula-panel\">\\[P(t)=L-Ae^{-kt}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 8","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Explain why 40(1.12)^t may be unsuitable for modelling a battery charge percentage for large t.</b></div><textarea class=\"student-note tall\" data-note=\"turn-8\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">It grows without bound and eventually exceeds 100%, violating the context.</div></details></div>","kind":"content","eyebrow":"Validity, saturation and shifted models"},{"section":"Concept cycle 8","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A high R² guarantees physically sensible extrapolation.”</p><h3>Repair</h3><p>Model form, bounds and assumptions must also be evaluated.</p></div></div>","kind":"content","eyebrow":"Validity, saturation and shifted models"},{"section":"Technology laboratory","title":"Interactive laboratory","html":"<div class=\"lab\"><h2>Change a parameter. Predict first. Test second.</h2><p>Graph both sides or use numerical solve for threshold equations; retain unrounded values and report the first whole time interval that satisfies a contextual condition.</p><div id=\"lesson-lab\" data-lab=\"2.4\"></div></div>","kind":"lab","eyebrow":"Technology with purpose"},{"section":"Technology laboratory","title":"GDC workflow","html":"<div class=\"workflow\"><div><b>1</b><span>Define variables and the valid domain.</span></div><div><b>2</b><span>Enter the model accurately.</span></div><div><b>3</b><span>Choose a window or list that reveals relevant behaviour.</span></div><div><b>4</b><span>Use trace, intersect, regression or solve.</span></div><div><b>5</b><span>Verify and interpret the output.</span></div></div>","kind":"content","eyebrow":"Repeatable process"},{"section":"Technology laboratory","title":"Interpreting calculator output","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Raw output</h2><p>A decimal, regression equation or graph feature is not yet a complete answer.</p></article><article class=\"focus-card\"><h2>IB response</h2><p>State the method, round appropriately, include units, select the contextual solution and explain what it means.</p></article></div>","kind":"content","eyebrow":"Technology → mathematics → context"},{"section":"Technology laboratory","title":"Precision and validation","html":"<div class=\"callout\"><b>Avoid premature rounding.</b> Store or retain full-precision values until the final line. Then test the result in the original model and check whether it belongs to the domain.</div><textarea class=\"student-note\" data-note=\"technology-check\" placeholder=\"Write the validation check you would use for this lesson.\"></textarea>","kind":"content","eyebrow":"Reliable evidence"},{"section":"Case study","title":"Case-study brief","html":"<div class=\"investigation\"><h2>Two quantities start together. One adds a fixed amount; the other grows by a fixed percentage. Which becomes larger, when does it happen, and how reliable is the prediction?</h2><p>Build a model, make at least two assumptions, use technology, and identify evidence that could reject your model.</p></div>","kind":"content","eyebrow":"Mini investigation"},{"section":"Case study","title":"Data and model choice","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Evidence</h2><p>Use numerical, graphical and contextual information. Look for constant differences, ratios, turning points, asymptotes, residual structure or restrictions.</p></article><article class=\"focus-card\"><h2>Choice</h2><p>Select the simplest defensible model. A more complex model requires stronger evidence and clearer parameter interpretation.</p></article></div>","kind":"content","eyebrow":"Model selection"},{"section":"Case study","title":"Decision and interpretation","html":"<div class=\"student-turn\"><h2>Write the decision sentence</h2><p>“According to the model, … because … . This conclusion is valid for … and assumes … .”</p><textarea class=\"student-note tall\" data-note=\"case-decision\" placeholder=\"Complete the sentence for the inquiry context.\"></textarea></div>","kind":"content","eyebrow":"Communicate like an IB student"},{"section":"Case study","title":"Evaluate and extend","html":"<div class=\"reflection-grid\"><div><h2>Validity</h2><p>Does the model reproduce known data and respect physical limits?</p></div><div><h2>Sensitivity</h2><p>How much does the conclusion change when inputs or parameters change?</p></div><div><h2>Extension</h2><p>What additional data or alternative model would strengthen the decision?</p></div></div>","kind":"content","eyebrow":"Reflection is mathematics"},{"section":"Communication","title":"Full-mark response checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"comm-1\"><span>I used the command term at the required depth.</span></label><label><input type=checkbox data-reflect=\"comm-2\"><span>I showed the equation, substitution or technology evidence.</span></label><label><input type=checkbox data-reflect=\"comm-3\"><span>I used correct notation, units and rounding.</span></label><label><input type=checkbox data-reflect=\"comm-4\"><span>I interpreted the result and addressed restrictions.</span></label><label><input type=checkbox data-reflect=\"comm-5\"><span>I evaluated assumptions when the question required judgment.</span></label></div>","kind":"content","eyebrow":"Before submitting"},{"section":"Communication","title":"Theory of Knowledge connection","html":"<div class=\"explain-prompt\"><h2>When does a useful model count as knowledge?</h2><p>Discuss whether predictive accuracy, explanatory mechanism, transparent assumptions and reproducibility contribute differently to trust.</p><textarea class=\"student-note tall\" data-note=\"tok\" placeholder=\"Write a claim, counterclaim and example.\"></textarea></div>","kind":"content","eyebrow":"TOK"},{"section":"Communication","title":"Internal assessment connection","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Possible exploration move</h2><p>Collect or source data, justify a function family, estimate parameters, analyse residuals and discuss limitations.</p></article><article class=\"focus-card\"><h2>Personal engagement</h2><p>Make a mathematical decision in a context you genuinely understand; do not merely reproduce calculator output.</p></article></div>","kind":"content","eyebrow":"IA thinking"},{"section":"Communication","title":"Exam strategy","html":"<div class=\"workflow\"><div><b>Read</b><span>Underline command terms, domain and requested precision.</span></div><div><b>Plan</b><span>Choose algebra, graph, table or regression deliberately.</span></div><div><b>Execute</b><span>Record method and retain full precision.</span></div><div><b>Interpret</b><span>Return to context and units.</span></div><div><b>Check</b><span>Substitute, compare or inspect residuals.</span></div></div>","kind":"content","eyebrow":"Five moves"},{"section":"Closure","title":"Mixed exit ticket","html":"<div class=\"exit-grid\"><div><b>Represent</b><span>Give two representations of one idea from Exponential and Logarithmic Models.</span></div><div><b>Calculate</b><span>Create and solve a numerical example.</span></div><div><b>Interpret</b><span>Explain a parameter or feature with units.</span></div><div><b>Evaluate</b><span>State one assumption and one limitation.</span></div></div><textarea class=\"student-note tall\" data-note=\"exit\" placeholder=\"Complete all four prompts.\"></textarea>","kind":"content","eyebrow":"Synthesis"},{"section":"Closure","title":"Mastery checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"master-2.4-0\"><span>Interpret parameters in exponential growth and decay models.</span></label><label><input type=checkbox data-reflect=\"master-2.4-1\"><span>Solve exponential equations graphically and with logarithms where appropriate.</span></label><label><input type=checkbox data-reflect=\"master-2.4-2\"><span>Use doubling time, half-life and asymptotic behaviour in context.</span></label><label><input type=checkbox data-reflect=\"master-2.4-3\"><span>Interpret logarithmic scales and compare additive with multiplicative change.</span></label></div>","kind":"content","eyebrow":"Can you do this independently?"},{"section":"Closure","title":"Next route","html":"<div class=\"connection-grid\"><button class=\"primary-btn route-jump\" data-go=\"practice\">Practice Studio · 60 questions</button><button class=\"secondary-btn route-jump\" data-go=\"exam\">IB Tasks · 3 extended responses</button><button class=\"secondary-btn route-jump\" data-go=\"quiz\">Timed Quiz · 12 questions</button><button class=\"secondary-btn route-jump\" data-go=\"review\">Mastery review</button></div>","kind":"content","eyebrow":"Choose evidence"},{"section":"Closure","title":"Lesson complete","html":"<div class=\"launch-panel\"><h2>Exponential and Logarithmic Models</h2><p>You have completed the Learn route. Use Practice Studio, IB Tasks and the independent quiz to turn familiarity into durable evidence.</p><button class=\"primary-btn route-jump\" data-go=\"review\">Open mastery and mark completion</button></div>","kind":"content","eyebrow":"Bridge to practice"}],"practice":[{"id":"IBAI-2.4-P01","level":"Foundation","prompt":"A quantity starts at 500 and grows by 4% per period. State the growth factor.","answer":"\\(1.04\\)","solution":"Growth factor=1+0.04.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":1.04,"tolerance":1.04e-05}},{"id":"IBAI-2.4-P02","level":"Foundation","prompt":"A value depreciates by 17% per year. State the decay factor.","answer":"\\(0.83\\)","solution":"Decay factor=1−0.17.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":0.83,"tolerance":8.3e-06}},{"id":"IBAI-2.4-P03","level":"Foundation","prompt":"For \\(A(t)=240(1.06)^t\\), write down A(0).","answer":"\\(240\\)","solution":"Any non-zero base to power 0 is 1.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"number","value":240.0,"tolerance":0.0024000000000000002}},{"id":"IBAI-2.4-P04","level":"Foundation","prompt":"Calculate \\(300(1.08)^3\\).","answer":"\\(377.914\\)","solution":"Substitute t=3 and evaluate.","marks":2,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":377.91360000000003,"tolerance":0.01}},{"id":"IBAI-2.4-P05","level":"Foundation","prompt":"Calculate \\(850(0.92)^4\\).","answer":"\\(608.934\\)","solution":"Use the decay factor 0.92 four times.","marks":2,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":608.934016,"tolerance":0.01}},{"id":"IBAI-2.4-P06","level":"Foundation","prompt":"State the horizontal asymptote of \\(f(x)=7(0.6)^x+12\\).","answer":"\\(y=12\\)","solution":"The vertical shift is 12.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":12.0,"tolerance":0.00012000000000000002}},{"id":"IBAI-2.4-P07","level":"Foundation","prompt":"State the y-intercept of \\(g(x)=4(1.5)^x-3\\).","answer":"\\(1\\)","solution":"g(0)=4−3=1.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":1.0,"tolerance":1e-05}},{"id":"IBAI-2.4-P08","level":"Foundation","prompt":"Evaluate \\(\\log_{10}(100000)\\).","answer":"\\(5\\)","solution":"100000=10⁵.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.4-P09","level":"Foundation","prompt":"Evaluate \\(\\log_2(1/8)\\).","answer":"\\(-3\\)","solution":"1/8=2⁻³.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-3.0,"tolerance":3.0000000000000004e-05}},{"id":"IBAI-2.4-P10","level":"Foundation","prompt":"Solve \\(2^x=32\\).","answer":"\\(5\\)","solution":"32=2⁵.","marks":2,"calculator":"No GDC required","command":"Solve","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.4-P11","level":"Foundation","prompt":"A pH value is \\(pH=-\\log_{10}(10^{-6})\\). Find the pH.","answer":"\\(6\\)","solution":"−log₁₀(10⁻⁶)=6.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":6.0,"tolerance":6.000000000000001e-05}},{"id":"IBAI-2.4-P12","level":"Foundation","prompt":"Which table suggests exponential change?","answer":"Ratios are all 1.2.","solution":"Constant ratios indicate exponential change.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["Differences are all 5.","Ratios are all 1.2.","Second differences are all 3.","Outputs are constant."],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.4-P13","level":"Foundation","prompt":"Which model shows exponential decay toward 20?","answer":"30(0.8)^x+20","solution":"The factor 0.8 decays and the vertical shift gives asymptote 20.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["20(0.8)^x","50(1.2)^x+20","30(0.8)^x+20","20−3x"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.4-P14","level":"Foundation","prompt":"If a quantity doubles every 6 hours, find its factor after 18 hours.","answer":"\\(8\\)","solution":"18 hours contains 3 doubling intervals, so factor 2³=8.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":8.0,"tolerance":8e-05}},{"id":"IBAI-2.4-P15","level":"Foundation","prompt":"If a quantity halves every 4 days, find the fraction remaining after 12 days.","answer":"\\(1/8\\)","solution":"Three half-lives: (1/2)³=1/8.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":0.125,"tolerance":1.25e-06}},{"id":"IBAI-2.4-P16","level":"Application","prompt":"A population starts at 1250 and grows by 3.2% per year. Find the population after 8 years.","answer":"\\(1608.228\\)","solution":"Use P=1250(1.032)^8.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1608.2278971361761,"tolerance":1}},{"id":"IBAI-2.4-P17","level":"Application","prompt":"A laptop worth QAR 6200 depreciates by 21% each year. Find its value after 5 years.","answer":"QAR \\(1907.77\\)","solution":"Use V=6200(0.79)^5.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1907.7749673800004,"tolerance":1}},{"id":"IBAI-2.4-P18","level":"Application","prompt":"A culture follows \\(N(t)=480(1.18)^t\\). Find the first whole t for which N exceeds 1500.","answer":"\\(7\\)","solution":"Solve t>ln(1500/480)/ln(1.18)≈6.88, so the first whole period is 7.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":7.0,"tolerance":1e-06}},{"id":"IBAI-2.4-P19","level":"Application","prompt":"A medication amount is \\(A(t)=90(0.74)^t\\) mg. Find the first whole hour for which A<10 mg.","answer":"\\(8\\)","solution":"Solve t>ln(10/90)/ln(0.74)≈7.30; first whole hour 8.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":8.0,"tolerance":8e-05}},{"id":"IBAI-2.4-P20","level":"Application","prompt":"The value \\(P(t)=120-95e^{-0.28t}\\). Find P(6).","answer":"\\(102.294\\)","solution":"Substitute t=6; the model approaches 120.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":102.29447227625606,"tolerance":0.01}},{"id":"IBAI-2.4-P21","level":"Application","prompt":"Find the doubling time for 5.5% growth per year.","answer":"\\(12.946\\text{ years}\\)","solution":"T₂=ln2/ln1.055.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":12.946157112237172,"tolerance":0.01}},{"id":"IBAI-2.4-P22","level":"Application","prompt":"Find the half-life of a quantity that retains 88% each day.","answer":"\\(5.422\\text{ days}\\)","solution":"T₁/₂=ln0.5/ln0.88.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.422270979580217,"tolerance":0.01}},{"id":"IBAI-2.4-P23","level":"Application","prompt":"Hydrogen-ion concentration is \\(3.2\\times10^{-5}\\). Find pH.","answer":"\\(4.495\\)","solution":"pH=−log₁₀(3.2×10⁻⁵).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":4.494850021680094,"tolerance":0.01}},{"id":"IBAI-2.4-P24","level":"Application","prompt":"A sound scale is \\(L=10\\log_{10}(I/I_0)\\). Find L when \\(I/I_0=10^4\\).","answer":"\\(40\\)","solution":"10log₁₀(10⁴)=40.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":40.0,"tolerance":0.0004}},{"id":"IBAI-2.4-P25","level":"Application","prompt":"A model \\(C(t)=18+72(0.65)^t\\) gives temperature. Find the limiting temperature.","answer":"\\(18^\\circ\\text{C}\\)","solution":"The exponential term tends to 0.","marks":2,"calculator":"GDC permitted","command":"State","hint":"","tags":[],"check":{"mode":"number","value":18.0,"tolerance":0.00018}},{"id":"IBAI-2.4-P26","level":"Application","prompt":"An account grows from 8000 to 11 500 in 6 years under \\(A=8000b^t\\). Find b.","answer":"\\(1.0624\\)","solution":"b=(11500/8000)^(1/6).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1.0623508642950785,"tolerance":0.0001}},{"id":"IBAI-2.4-P27","level":"Application","prompt":"A disease incidence drops from 420 to 150 in 9 months under \\(N=420b^t\\). Find the monthly percentage decrease.","answer":"\\(10.81\\%\\)","solution":"b=(150/420)^(1/9); decrease=(1−b)×100%.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":10.810080017182678,"tolerance":0.05}},{"id":"IBAI-2.4-P28","level":"Application","prompt":"A city has 48 000 residents and grows at 2.1% annually. Find the expected increase during year 1.","answer":"\\(1008\\)","solution":"First-year increase=0.021(48000).","marks":2,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1008.0000000000001,"tolerance":0.010080000000000002}},{"id":"IBAI-2.4-P29","level":"Application","prompt":"A battery model is \\(B(t)=20(1.15)^t\\). Explain one reason to restrict the domain.","answer":"The model eventually predicts more than 100% charge, so it should be restricted to the charging interval or replaced by a bounded model.","solution":"Context imposes an upper limit.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["exceeds 100","battery capped","valid only until full"]}},{"id":"IBAI-2.4-P30","level":"Application","prompt":"A logarithmic scale is \\(S=\\log_{10}A\\). If A increases by a factor of 1000, find the change in S.","answer":"\\(3\\)","solution":"log₁₀(1000A)−log₁₀A=3.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":3.0,"tolerance":3.0000000000000004e-05}},{"id":"IBAI-2.4-P31","level":"Reasoning","prompt":"Which feature distinguishes exponential from linear growth?","answer":"Constant ratio","solution":"Equal input steps produce a constant multiplicative ratio.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["Constant difference","Constant ratio","Constant second difference","Finite domain"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.4-P32","level":"Reasoning","prompt":"Explain why \\(A(t)=500(1.04)^t\\) does not increase by the same amount each year.","answer":"Each 4% increase is calculated from a growing current value, so the absolute annual increase becomes larger.","solution":"The ratio is constant, not the difference.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["percentage of current","amount grows","compounding"]}},{"id":"IBAI-2.4-P33","level":"Reasoning","prompt":"For y=−6(0.7)^x+12, where is the graph relative to the asymptote?","answer":"Below y=12","solution":"The exponential term is positive and multiplied by −6, so y<12.","marks":2,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"choices":["Above y=12","Below y=12","Crosses y=12 repeatedly","On x=12"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.4-P34","level":"Reasoning","prompt":"Explain why an exponential growth model may fit a population only for a limited time.","answer":"Resources, space and other constraints eventually reduce the growth rate, so unbounded exponential growth becomes unrealistic.","solution":"A bounded model may be needed.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["resources limited","carrying capacity","growth slows"]}},{"id":"IBAI-2.4-P35","level":"Reasoning","prompt":"If concentration increases tenfold, how does pH=−log₁₀C change?","answer":"Decreases by 1","solution":"The logarithm increases by 1, and the negative sign makes pH decrease by 1.","marks":2,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"choices":["Increases by 10","Increases by 1","Decreases by 1","Does not change"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.4-P36","level":"Reasoning","prompt":"A model has b=0.97. Which description is correct?","answer":"3% decay","solution":"1−0.97=0.03, so 3% decay.","marks":2,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"choices":["3% growth","97% growth","3% decay","97% decay"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.4-P37","level":"Reasoning","prompt":"A threshold solution is t=5.27 months, but observations are monthly. Explain how to report the first month after the threshold is exceeded.","answer":"Check the inequality and report month 6, because the threshold is not reached at the end of month 5.","solution":"Contextual discrete time requires a ceiling, not ordinary rounding.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["6 months","round up","ceiling"]}},{"id":"IBAI-2.4-P38","level":"Reasoning","prompt":"Which expression has horizontal asymptote y=−4?","answer":"3(1.2)^x−4","solution":"The vertical shift is −4.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["3(1.2)^x−4","−4(1.2)^x+3","3x−4","log x−4"],"correct":0,"check":{"mode":"choice","value":0}},{"id":"IBAI-2.4-P39","level":"Reasoning","prompt":"Explain why \\(\\log_{10}(-5)\\) has no real value.","answer":"Positive powers of 10 are always positive, so no real exponent produces −5; logarithm arguments must be positive.","solution":"This is a domain restriction.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["no real exponent","positive base powers positive","argument must be positive"]}},{"id":"IBAI-2.4-P40","level":"Reasoning","prompt":"Two models start at the same positive value. One is linear with positive slope and one is exponential with factor 1.05. Which statement is always true for sufficiently large t?","answer":"Exponential becomes larger","solution":"Positive exponential growth eventually exceeds positive linear growth.","marks":2,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"choices":["Linear remains larger","Exponential becomes larger","They stay equal","Both decrease"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.4-P41","level":"Reasoning","prompt":"A model has R²=0.99 but predicts 140% market share. Comment.","answer":"The fit statistic does not override contextual bounds; a prediction above 100% is impossible and signals invalid extrapolation or model form.","solution":"Evaluate feasibility, not only fit.","marks":3,"calculator":"No GDC required","command":"Comment","hint":"","tags":[],"check":{"mode":"text","accepted":["impossible","context invalid","restrict model"]}},{"id":"IBAI-2.4-P42","level":"Reasoning","prompt":"What does a half-life of 8 hours mean?","answer":"The amount is halved every 8 hours.","solution":"Half-life describes a multiplicative reduction over each 8-hour interval.","marks":2,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"choices":["The amount decreases by 8 units each hour.","The amount is halved every 8 hours.","The amount reaches zero after 16 hours.","The factor is 8."],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.4-P43","level":"Reasoning","prompt":"Explain why the asymptote in \\(y=20+80e^{-0.4t}\\) is physically plausible for a cooling object in a 20°C room.","answer":"The object approaches the ambient room temperature 20°C as the temperature difference decays.","solution":"The asymptote has contextual meaning.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["room temperature","approaches 20","equilibrium"]}},{"id":"IBAI-2.4-P44","level":"Reasoning","prompt":"Which equation is equivalent to \\(\\log_3 81=4\\)?","answer":"3⁴=81","solution":"The logarithm records the exponent on base 3.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"choices":["4³=81","3⁴=81","81³=4","3⁸¹=4"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.4-P45","level":"Reasoning","prompt":"A data table has ratios 1.20,1.18,1.21,1.19. Comment on an exponential model.","answer":"The ratios are close to constant, so an exponential model is a reasonable candidate, but residuals and context should still be checked.","solution":"Real data need not give exactly equal ratios.","marks":3,"calculator":"No GDC required","command":"Comment","hint":"","tags":[],"check":{"mode":"text","accepted":["approximately exponential","ratios nearly constant","reasonable candidate"]}},{"id":"IBAI-2.4-P46","level":"Challenge","prompt":"Solve \\(750(1.09)^t=2000\\).","answer":"\\(11.381\\)","solution":"Isolate the power and use logarithms.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":11.38147450899818,"tolerance":0.01}},{"id":"IBAI-2.4-P47","level":"Challenge","prompt":"Solve \\(120-100e^{-0.25t}=95\\).","answer":"\\(5.545\\)","solution":"e^(-0.25t)=0.25, so t=−ln0.25/0.25.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.545177444479562,"tolerance":0.01}},{"id":"IBAI-2.4-P48","level":"Challenge","prompt":"A population doubles in 14 years. Find the equivalent annual growth rate.","answer":"\\(5.076\\%\\)","solution":"b=2^(1/14); rate=(b−1)×100%.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.075663865321944,"tolerance":0.01}},{"id":"IBAI-2.4-P49","level":"Challenge","prompt":"A substance has half-life 9.5 hours. Find the percentage remaining after 30 hours.","answer":"\\(11.204\\%\\)","solution":"Fraction remaining=(1/2)^(30/9.5).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":11.204151201723198,"tolerance":0.05}},{"id":"IBAI-2.4-P50","level":"Challenge","prompt":"An exponential model \\(f(x)=ab^x+6\\) has f(0)=14 and f(3)=33. Find b.","answer":"\\(1.5\\)","solution":"a=8; 8b³+6=33, so b³=27/8.","marks":5,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1.5,"tolerance":0.0001}},{"id":"IBAI-2.4-P51","level":"Challenge","prompt":"A model \\(N(t)=L-450(0.8)^t\\) has N(0)=150. Find L.","answer":"\\(600\\)","solution":"150=L−450, so L=600.","marks":3,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":600.0,"tolerance":0.006}},{"id":"IBAI-2.4-P52","level":"Challenge","prompt":"Find the concentration C when pH=3.65.","answer":"\\(0.0002239\\)","solution":"C=10^(−pH).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":0.000223872113856834,"tolerance":1e-07}},{"id":"IBAI-2.4-P53","level":"Challenge","prompt":"Earthquake magnitude is \\(M=\\log_{10}A\\). Find the amplitude ratio of magnitudes 7.4 and 5.1.","answer":"\\(199.526\\)","solution":"A₁/A₂=10^(7.4−5.1).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":199.5262314968883,"tolerance":0.1}},{"id":"IBAI-2.4-P54","level":"Challenge","prompt":"The models \\(L(t)=400+70t\\) and \\(E(t)=400(1.12)^t\\) intersect again after t=0. Find the positive intersection time.","answer":"\\(7.183\\)","solution":"Graph or numerically solve 400+70t=400(1.12)^t and select the non-zero solution.","marks":5,"calculator":"GDC expected","command":"Solve","hint":"","tags":[],"check":{"mode":"number","value":7.1832131067425475,"tolerance":0.01}},{"id":"IBAI-2.4-P55","level":"Challenge","prompt":"A decay model is \\(A(t)=A_0e^{-kt}\\) and retains 35% after 8 hours. Find k.","answer":"\\(0.1312\\)","solution":"0.35=e^(−8k), so k=−ln0.35/8.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":0.13122776556233473,"tolerance":0.0001}},{"id":"IBAI-2.4-P56","level":"Challenge","prompt":"Compare models \\(600(1.04)^t\\) and \\(600+30t\\) over a very long time.","answer":"The exponential model eventually becomes larger because its absolute increase compounds, although the linear model may be larger for some early times.","solution":"Long-run behaviour differs from short-run comparison.","marks":4,"calculator":"No GDC required","command":"Compare","hint":"","tags":[],"check":{"mode":"text","accepted":["exponential larger","exponential eventually dominates","linear initially"]}},{"id":"IBAI-2.4-P57","level":"Challenge","prompt":"A bounded growth model is \\(P(t)=1000-880e^{-0.18t}\\). Find the first whole year when P>900.","answer":"\\(13\\)","solution":"Solve e^(−0.18t)<100/880, giving t>12.08; first whole year 13.","marks":5,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":13.0,"tolerance":0.00013000000000000002}},{"id":"IBAI-2.4-P58","level":"Challenge","prompt":"Solve \\(3.2\\log_{10}x=7.04\\).","answer":"\\(158.489\\)","solution":"log₁₀x=2.2, so x=10^2.2.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":158.48931924611125,"tolerance":0.01}},{"id":"IBAI-2.4-P59","level":"Challenge","prompt":"A model predicts 5% annual growth forever. Give two distinct assumptions that should be challenged.","answer":"Examples: the percentage rate remains constant; resources and capacity do not constrain growth; no policy, market or environmental shock changes the system.","solution":"Two different modelling assumptions are required.","marks":4,"calculator":"No GDC required","command":"Evaluate","hint":"","tags":[],"check":{"mode":"text","accepted":["constant rate","unlimited resources","no shocks","population conditions"]}},{"id":"IBAI-2.4-P60","level":"Challenge","prompt":"A logarithmic scale is \\(S=20\\log_{10}(A/A_0)\\). Find the change in S when amplitude triples.","answer":"\\(9.542\\)","solution":"Change=20log₁₀3.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":9.542425094393248,"tolerance":0.01}}],"quiz":[{"id":"IBAI-2.4-Q01","level":"Quiz","prompt":"State the growth factor for 7.5% growth.","answer":"\\(1.075\\)","solution":"1+0.075.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1.075,"tolerance":1.075e-05}},{"id":"IBAI-2.4-Q02","level":"Quiz","prompt":"State the decay factor for 12% decay.","answer":"\\(0.88\\)","solution":"1−0.12.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":0.88,"tolerance":8.8e-06}},{"id":"IBAI-2.4-Q03","level":"Quiz","prompt":"Calculate 950(1.03)^4.","answer":"\\(1069.233\\)","solution":"Substitute.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1069.2333695000002,"tolerance":0.01}},{"id":"IBAI-2.4-Q04","level":"Quiz","prompt":"State the horizontal asymptote of 9(0.5)^x−2.","answer":"\\(y=-2\\)","solution":"Vertical shift.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-2.0,"tolerance":2e-05}},{"id":"IBAI-2.4-Q05","level":"Quiz","prompt":"Evaluate log₁₀(0.0001).","answer":"\\(-4\\)","solution":"10⁻⁴.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-4.0,"tolerance":4e-05}},{"id":"IBAI-2.4-Q06","level":"Quiz","prompt":"Solve 5^x=125.","answer":"\\(3\\)","solution":"125=5³.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":3.0,"tolerance":3.0000000000000004e-05}},{"id":"IBAI-2.4-Q07","level":"Quiz","prompt":"Find the doubling time for 8% growth.","answer":"\\(9.006\\)","solution":"ln2/ln1.08.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":9.006468342000588,"tolerance":0.01}},{"id":"IBAI-2.4-Q08","level":"Quiz","prompt":"Find the half-life when the retention factor is 0.9.","answer":"\\(6.579\\)","solution":"ln0.5/ln0.9.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":6.578813478960585,"tolerance":0.01}},{"id":"IBAI-2.4-Q09","level":"Quiz","prompt":"Find pH when C=2.5×10⁻⁴.","answer":"\\(3.602\\)","solution":"−log₁₀C.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":3.6020599913279625,"tolerance":0.01}},{"id":"IBAI-2.4-Q10","level":"Quiz","prompt":"Explain why 300(1.1)^t is not suitable for long-term modelling of a percentage capped at 100.","answer":"It grows without bound and eventually violates the 100% cap.","solution":"Restrict or replace the model.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["exceeds 100","unbounded","cap"]}},{"id":"IBAI-2.4-Q11","level":"Quiz","prompt":"Which sequence is exponential?","answer":"20,30,45,67.5","solution":"Each term is multiplied by 1.5.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["20,25,30,35","20,30,45,67.5","20,24,30,38","20,20,20,20"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.4-Q12","level":"Quiz","prompt":"A magnitude scale is log₁₀A. If A is multiplied by 100, find the increase.","answer":"\\(2\\)","solution":"log₁₀100=2.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":2.0,"tolerance":2e-05}}],"exam":[{"id":"U2-2.4-T1","style":"Paper 2 · comparison","title":"Linear and exponential membership","calculator":"GDC expected","total_marks":11,"context":"Two clubs start with 600 members. Club L gains 85 members each year. Club E grows by 9% each year.","parts":[{"label":"a","prompt":"Write models L(t) and E(t).","marks":2,"answer":"\\(L(t)=600+85t\\), \\(E(t)=600(1.09)^t\\).","markscheme":"A1 each model."},{"label":"b","prompt":"Calculate both memberships after 8 years.","marks":3,"answer":"L(8)=1280; E(8)≈1196.","markscheme":"A1 linear; M1 exponential; A1 rounded value."},{"label":"c","prompt":"Use technology to find the first whole year in which E(t)>L(t).","marks":4,"answer":"Year 11: E(10)≈1420<L(10)=1450, while E(11)≈1548>L(11)=1535.","markscheme":"M1 solve/graph; A1 crossing; A1 integer check; A1 conclusion."},{"label":"d","prompt":"Evaluate both models for a 40-year forecast.","marks":2,"answer":"Both may ignore capacity and changing growth; the exponential model becomes especially sensitive and may be unrealistic without a limit.","markscheme":"R1 assumptions/limits; R1 long-term consequence."}]},{"id":"U2-2.4-T2","style":"Paper 2 · decay","title":"Medication concentration","calculator":"GDC expected","total_marks":10,"context":"A medication concentration is modelled by \\(C(t)=85(0.78)^t+4\\) mg/L, where t is measured in hours.","parts":[{"label":"a","prompt":"State the initial concentration and horizontal asymptote.","marks":2,"answer":"C(0)=89 mg/L; asymptote y=4 mg/L.","markscheme":"A1 each."},{"label":"b","prompt":"Calculate C(6).","marks":2,"answer":"\\(C(6)\\approx23.1\\) mg/L.","markscheme":"M1 substitution; A1 value to three significant figures."},{"label":"c","prompt":"Find when C(t) first falls below 10 mg/L.","marks":4,"answer":"Solve \\(85(0.78)^t+4=10\\): \\(t\\approx10.7\\) h, so after about 10.7 h (or first whole hour 11).","markscheme":"M1 isolate; M1 logarithm/technology; A1 time; A1 contextual rounding."},{"label":"d","prompt":"Explain why 4 is not the half-life level.","marks":2,"answer":"The model decays toward 4, so half-life applies to the excess C−4, not the full concentration.","markscheme":"R1 shifted asymptote; R1 correct quantity."}]},{"id":"U2-2.4-T3","style":"Paper 1/2 bridge","title":"Acidity and logarithmic comparison","calculator":"GDC expected","total_marks":10,"context":"The acidity scale is \\(pH=-\\log_{10}C\\), where C is the hydrogen-ion concentration in mol/L.","parts":[{"label":"a","prompt":"Calculate the pH when \\(C=3.2\\times10^{-5}\\).","marks":2,"answer":"pH≈4.49.","markscheme":"M1 substitution; A1 value."},{"label":"b","prompt":"A second solution has concentration eight times as large. Find its pH.","marks":3,"answer":"\\(pH_2=pH_1-\\log_{10}8\\approx3.59\\).","markscheme":"M1 ratio/log relation; A1 calculation; A1 value."},{"label":"c","prompt":"Interpret the difference in pH.","marks":2,"answer":"The second solution is more acidic; multiplying concentration by 8 lowers pH by about 0.903.","markscheme":"A1 direction; A1 quantitative interpretation."},{"label":"d","prompt":"Explain why differences rather than raw pH ratios should be used to compare concentrations.","marks":3,"answer":"pH is logarithmic; a difference represents a concentration ratio, whereas a ratio of pH numbers has no direct multiplicative concentration meaning.","markscheme":"R1 logarithmic scale; R1 difference/ratio link; R1 conclusion."}]}],"counts":{"slides":64,"practice":60,"quiz":12,"exam":3},"rights":{"student_content":"Original ECHS-authored instructional and assessment content","private_bank_policy":"No source-bank prompt, canonical ID, provenance record or rights record is embedded in public lesson assets."}};
